import{loadWetlandNPCs}from'./npc-presentation.mjs';
import{prepareWetlandSupport}from'./support.mjs';import{loadWetlandEnvironment}from'./environment/load.mjs';import{loadSelectedPlayerFrames}from'../gohyeon-pair/player_frames/load-player-frames.mjs';import{selectPlayerFrame}from'../gohyeon-pair/player-frame.mjs';import{createFrameLighting}from'./environment/common/frame-lighting.mjs';
const origin=([x,y])=>[Math.max(0,Math.min(1876,x-480)),Math.max(0,Math.min(1280,y-270))];
export async function prepareWetlandRegion({signal,fetcher=fetch,decode=b=>createImageBitmap(new Blob([b])),decodeRGBA,inflate,getElapsedMs,canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}={}){
 let closed=false,support=null,environment=null,actors=null,npcs=null,actorCanvas=null;const rgba=new Map(),shade=createFrameLighting({nightTint:[.4,.47,.6]});const check=()=>{if(closed||signal?.aborted)throw Error('WETLAND_REGION_CLOSED')};
 const dispose=()=>{if(closed)return;closed=true;let first;for(const own of[environment,npcs,actors,support])try{own?.dispose()}catch(e){first??=e}environment=null;npcs=null;actors=null;support=null;rgba.clear();try{if(actorCanvas)actorCanvas.width=actorCanvas.height=1}catch(e){first??=e}finally{actorCanvas=null}if(first)throw first};
 try{support=await prepareWetlandSupport('wetland',{fetcher,signal});actors=await loadSelectedPlayerFrames({fetcher:async u=>{check();return fetcher(u,{signal})},decode:async b=>{check();const image=await decode(b);if(closed||signal?.aborted){try{image.close?.()}finally{throw Error('WETLAND_REGION_CLOSED')}}return image}});check();actorCanvas=canvasFactory(107,107);const g=actorCanvas.getContext('2d');for(const[k,im]of Object.entries(actors.actors)){g.clearRect(0,0,107,107);g.drawImage(im,0,0);rgba.set(k,g.getImageData(0,0,107,107).data)}npcs=await loadWetlandNPCs({fetcher,decode,signal,canvasFactory});check();environment=await loadWetlandEnvironment({fetcher,decodeRGBA,inflate,signal,getElapsedMs});check();return Object.freeze({get pins(){return support.pins},supportPinsVerified:true,safe:f=>!closed&&support.safe(f),validate:n=>closed?'WETLAND_REGION_CLOSED':support.validate(n),resetCameraForSceneOrRestore(f){check();if(!support.safe(f))throw Error('WETLAND_FOOT');return origin(f)},draw(ctx,{foot,facing,elapsedMs=0,moving=false,minutes=720,lights=true,rest=false}){check();if(!support.safe(foot)||!['up','down','left','right'].includes(facing))throw Error('WETLAND_POSE');if(ctx.canvas.width!==960||ctx.canvas.height!==540)throw Error('WETLAND_VIEWPORT');const o=origin(foot),frame=selectPlayerFrame({facing,walking:moving,elapsedMs}),rendered=environment.frame({camera:[...o,960,540],ms:elapsedMs,minutes,lightOn:lights,rest});if(rendered.skipped)return rendered;ctx.save();try{const im=ctx.createImageData(960,540);im.data.set(rendered.pixels);ctx.putImageData(im,0,0);const ag=actorCanvas.getContext('2d'),a=ag.createImageData(107,107);shade(rgba.get('actor:'+frame),a.data,rendered.stats.nightMix);ag.putImageData(a,0,0);ctx.imageSmoothingEnabled=false;const layers=npcs.drawLayers(ctx,o,rendered.stats.nightMix);layers.push({y:foot[1],draw:()=>ctx.drawImage(actorCanvas,foot[0]-o[0]-53,foot[1]-o[1]-90)});layers.sort((a,b)=>a.y-b.y);for(const layer of layers)layer.draw()}finally{ctx.restore()}return{skipped:false,presentationMs:elapsedMs,effectMs:rendered.effectMs,heldEffect:rendered.heldEffect,exactRequestedPhase:rendered.exactRequestedPhase,camera:o,environment:rendered.stats}},stats(){check();return environment.stats()},settled(){check();return environment.settled()},dispose})}catch(e){try{dispose()}catch{}throw e}
}
